# P32: check exactly the supplied witness for line 13 ("Since G/G'~Z(G)"):
# "For G = S_3, G/G' has order 2 but Z(G) is the trivial group."
from itertools import permutations

G = list(permutations(range(3)))                 # S_3 as tuples: p[i] = image of i
def mul(p, q): return tuple(p[q[i]] for i in range(3))
def inv(p):
    r = [0] * 3
    for i, v in enumerate(p): r[v] = i
    return tuple(r)
e = (0, 1, 2)

# derived subgroup G' = subgroup generated by all commutators [a,b] = a b a^-1 b^-1
comms = {mul(mul(a, b), mul(inv(a), inv(b))) for a in G for b in G}
Gp = set(comms)
changed = True
while changed:                                    # close under products
    changed = False
    for x in list(Gp):
        for y in list(Gp):
            z = mul(x, y)
            if z not in Gp:
                Gp.add(z); changed = True
Z = {a for a in G if all(mul(a, b) == mul(b, a) for b in G)}

print("|G| = |S_3| =", len(G))
print("commutators:", sorted(comms))
print("G' = [G,G] =", sorted(Gp), " |G'| =", len(Gp))
print("|G/G'| =", len(G) // len(Gp))
print("Z(G) =", sorted(Z), " |Z(G)| =", len(Z))
print()
print("response's numbers reproduce (|G/G'| = 2, Z(G) trivial)? ",
      len(G) // len(Gp) == 2 and Z == {e})
print("G/G' isomorphic to Z(G)?  (orders must agree)",
      (len(G) // len(Gp)) == len(Z))
